            });
          return [league.id, games] as const;
        }),
      );
      return Object.fromEntries(entries) as Record<string, Game[]>;
    },
    { refreshInterval: 10000 },
  );

  const hasAnyLiveGames = liveLeagues.some(
    (league) => (liveGamesByLeague?.[league.id]?.length ?? 0) > 0,
