    private final String teamOrder;
    private final boolean supportsOdds;
    private final boolean supportsLiveDetails;

    League(Sport sport,
           String value,
           String label,
           boolean supportsYearFilter,
           boolean supportsWeekFilter,
           boolean supportsStandings,
           String contextMode,
           String statsProfile,
