        this.supportsWeekFilter = supportsWeekFilter;
        this.supportsStandings = supportsStandings;
        this.contextMode = contextMode;
        this.statsProfile = statsProfile;
        this.teamOrder = teamOrder;
        this.supportsOdds = supportsOdds;
