3	import com.tallyo.tallyo_backend.dto.ApiError;
4	import jakarta.servlet.http.HttpServletRequest;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ResponseEntity;
7	import org.springframework.web.client.ResourceAccessException;
8	import org.springframework.web.client.RestClientException;
9	import org.springframework.web.bind.annotation.ExceptionHandler;
10	import org.springframework.web.bind.annotation.RestControllerAdvice;
11	
12	import java.time.DateTimeException;
13	import java.time.Instant;
14	
15	@RestControllerAdvice
16	public class GlobalExceptionHandler {
17	
18	    @ExceptionHandler(InvalidRequestException.class)
19	    public ResponseEntity<ApiError> handleInvalidRequest(
20	            InvalidRequestException ex,
21	            HttpServletRequest request
22	    ) {
23	        return ResponseEntity.badRequest().body(
24	                buildError("BAD_REQUEST", ex.getMessage(), null, request)
25	        );
26	    }
27	
28	    @ExceptionHandler(DateTimeException.class)
29	    public ResponseEntity<ApiError> handleDateTimeException(
30	            DateTimeException ex,
31	            HttpServletRequest request
32	    ) {
33	        return ResponseEntity.badRequest().body(
34	                buildError("INVALID_TIMEZONE", "Invalid timezone", ex.getMessage(), request)
35	        );
36	    }
37	
38	    @ExceptionHandler({ResourceAccessException.class, RestClientException.class})
39	    public ResponseEntity<ApiError> handleUpstreamServiceException(
40	            RestClientException ex,
41	            HttpServletRequest request
42	    ) {
43	        return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(
44	                buildError(
45	                        "UPSTREAM_SERVICE_UNAVAILABLE",
46	                        "Unable to reach upstream sports data provider",
47	                        extractDetails(ex),
48	                        request
49	                )
50	        );
51	    }
52	
53	    @ExceptionHandler(Exception.class)
54	    public ResponseEntity<ApiError> handleUnexpectedException(
55	            Exception ex,
56	            HttpServletRequest request
57	    ) {
58	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(
59	                buildError(
60	                        "INTERNAL_ERROR",
61	                        "An unexpected error occurred",
62	                        extractDetails(ex),
63	                        request
64	                )
65	        );
66	    }
67	
68	    private String extractDetails(Throwable throwable) {
69	        if (throwable == null) {
70	            return null;
71	        }
72	
73	        Throwable root = throwable;
74	        while (root.getCause() != null && root.getCause() != root) {
75	            root = root.getCause();
76	        }
77	
78	        String top = throwable.getMessage();
79	        String bottom = root.getMessage();
80	
81	        if (bottom == null || bottom.isBlank() || root == throwable) {
82	            return top;
83	        }
84	
85	        String rootSummary = root.getClass().getSimpleName() + ": " + bottom;
86	        return (top == null || top.isBlank()) ? rootSummary : top + " | root cause: " + rootSummary;
87	    }
88	
89	    private ApiError buildError(String code, String message, String details, HttpServletRequest request) {
90	        return ApiError.builder()
91	                .code(code)
92	                .message(message)
93	                .details(details)
94	                .path(request.getRequestURI())
95	                .timestamp(Instant.now().toString())
96	                .build();
97	    }
98	}
