        Tallyo
      </div>
      <div className="p-1 text-gray-900 dark:text-white">
        A simple scoreboard
      </div>
      <nav className="space-x-4">
        {links.map((link) => (
          <Link
            key={link.href}
            href={link.href}
            className={`p-1 rounded-md font-medium transition-colors duration-200 hover:text-white
              ${
                pathname === link.href
                  ? "border border-gray-300 dark:border-gray-500"
