    >
      <span>{title}</span>
      <ChevronDown
        textAnchor="end"
        className={`w-5 h-5  transition-transform duration-300 ${
          isOpen ? "rotate-180" : ""
        }`}
      ></ChevronDown>
    </button>
  );
};
