interface SelectorProps {
  data: string[];
  currentValue: string;
  setCurrentValue: (str: string) => void;
  displayString?: string | undefined;
  displayMap?: Map<string, string> | undefined;
}

const Selector: React.FC<SelectorProps> = ({
  data,
  currentValue,
  setCurrentValue,
  displayString,
  displayMap,
}) => {
  return (
    <div>
