465	  const [isStandingsOpen, setIsStandingsOpen] = useState<boolean>(false);
466	  const [sortByScope, setSortByScope] = useState<
467	    Record<string, { columnId: string; direction: SortDirection }>
468	  >({});
469	
470	  const toggleOpenStandings = (id: string) => {
471	    setOpenStandings((prev) => ({ ...prev, [id]: !prev[id] }));
472	  };
473	
474	  const getSortState = (scopeKey: string) => sortByScope[scopeKey] ?? null;
475	
476	  const toggleSort = (columnId: string, scopeKey: string) => {
477	    setSortByScope((prev) => {
478	      const current = prev[scopeKey];
479	      const next = { ...prev };
480	      if (!current || current.columnId !== columnId) {
481	        next[scopeKey] = { columnId, direction: "desc" };
482	        return next;
483	      }
484	      if (current.direction === "desc") {
485	        next[scopeKey] = { columnId, direction: "asc" };
486	        return next;
487	      }
488	      delete next[scopeKey];
489	      return next;
490	    });
491	  };
492	
493	  const getSortedRows = (rows: StandingsRow[], scopeKey: string) => {
494	    const sortState = getSortState(scopeKey);
495	    if (!sortState) {
496	      return rows;
497	    }
498	
499	    const sortColumn = profile.columns.find(
500	      (col) => col.id === sortState.columnId,
501	    );
502	    if (!sortColumn?.sortValue) {
503	      return rows;
504	    }
505	
506	    const sorted = [...rows].sort((a, b) => {
507	      const aValue = sortColumn.sortValue!(a.team);
508	      const bValue = sortColumn.sortValue!(b.team);
509	      if (typeof aValue === "number" && typeof bValue === "number") {
510	        return aValue - bValue;
511	      }
512	      return String(aValue).localeCompare(String(bValue));
513	    });
514	
515	    return sortState.direction === "desc" ? sorted.reverse() : sorted;
516	  };
517	
518	  return (
519	    <div className="divide-x divide-gray-500">
520	      <CollapsableSection
521	        title={profile.title}
522	        isOpen={isStandingsOpen}
523	        onToggle={() => setIsStandingsOpen(!isStandingsOpen)}
524	      />
525	      {isStandingsOpen && isLoading && <div>Loading...</div>}
526	      {isStandingsOpen &&
527	        !isLoading &&
528	        standings.map((standing) => (
529	          <div key={standing.groupName}>
530	            <CollapsableSection
531	              title={standing.groupName}
532	              isOpen={openStandings[standing.groupName]}
533	              onToggle={() => toggleOpenStandings(standing.groupName)}
534	            />
535	
536	            {openStandings[standing.groupName] && (
537	              <div className="overflow-x-auto">
538	                <div className="min-w-[700px]">
539	                  {profile.buildSections(standing).map((section) => {
540	                    const scopeKey =
541	                      profile.sortScope === "global" ? "global" : section.key;
542	                    const sortState = getSortState(scopeKey);
543	                    const sortedRows = getSortedRows(section.rows, scopeKey);
544	
545	                    return (
546	                      <div key={section.key}>
547	                        {section.title && (
548	                          <div className="px-2 py-1 border border-gray-500 font-medium">
549	                            {section.title}
550	                          </div>
551	                        )}
552	                        <div
553	                          className="px-1 grid border border-gray-500 divide-x divide-gray-500"
554	                          style={{
555	                            gridTemplateColumns: `repeat(${profile.columns.length}, minmax(0, 1fr))`,
556	                          }}
557	                        >
558	                          {profile.columns.map((col) => (
559	                            <div
560	                              key={col.id}
561	                              className={`p-1 ${
562	                                col.sticky
563	                                  ? "sticky left-0 z-20 bg-sky-50 dark:bg-neutral-800"
564	                                  : ""
565	                              }`}
566	                            >
567	                              {col.sortValue ? (
568	                                <button
